end

function UIMainChapterSideLinePopupDialog:OnBtnClose()
    UIModule.BackDialog()
end

function UIMainChapterSideLinePopupDialog:InitData()
    print(table.dump(questComponent._sideInfo))
    self._allListData = {}

    local t = QuestConfMgr:GetInstance():GetAllSideTypes(self._curChapterId)

    for k, v in pairs(t) do
        table.insert(self._allListData, {
            id = v,
            type = 1,
        })

        local t1 = QuestConfMgr:GetInstance():GetAllSideIds(v)
        for _, id in pairs(t1) do
            table.insert(self._allListData, {
                id = id,
                type = 2,
            })
        end
    end
end

function UIMainChapterSideLinePopupDialog:FillSelf()
    local vo = QuestConfMgr:GetInstance():GetChapterVoByID(self._curChapterId)
    if not vo then
        return
    end

    CfUtils.FillText(self.TxtNubmer, vo.number)
    CfUtils.FillText(self.TxtTitle, vo.name)

    self:RefreshList()
end

function UIMainChapterSideLinePopupDialog:GetCurInd()
    for k, v in pairs(self._allListData) do
        local isUnlock, err = QuestConfMgr:GetInstance():IsUnlockSideQuest(v.id)
        local isPass = QuestConfMgr:GetInstance():IsPassSideQuest(v.id) 
        if isUnlock and not isPass then
            return k - 1
        end
    end 
    return 0
end

function UIMainChapterSideLinePopupDialog:RefreshList()
    if self._isInitLoopList then
        GameUtils.ReloadData(self.ScrollView, table.count(self._allListData))
    else
        self.ScrollView:InitListView(table.count(self._allListData), Bind(self, self.OnRefreshIndex))
        self._isInitLoopList = true
    end
end

function UIMainChapterSideLinePopupDialog:OnRefreshIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end
    local cell
    local data = self._allListData[index + 1]
    
    if checkNumber(data.type) == 1 then
        cell = listView:NewListViewItem("Cell1")
    else
        cell = listView:NewListViewItem("Cell2")
    end
    local go = cell.gameObject

    if checkNumber(data.type) == 1 then
        local vo = QuestConfMgr:GetInstance():GetQuestSideTypeVo(data.id)
        if vo then
            CfUtils.FillText(go.transform:Find("TitleGroup/TxtTitle"), vo.name)
        end
    else
        local scr = CfUtils.GetLuaScr(go, "Game.UI.FightReady.UIMainChapter.UIMainChapter.UIMainChapterSideLinePopupNode")
        if scr then
            scr:Refresh(data.id, function()                
                self:PlayPlot(data.id, function()
                    local isPass = QuestConfMgr:GetInstance():IsPassSideQuest(data.id)
                    if isPass then

                    else
                        questComponent:OverseaMainQuestSideStoryReq(data.id, function(data)
                            UIModule.OpenDialog({id = Constants.UITypeIds.UICommonRewardPop, parameters = {rewards = data}})
                            self:RefreshList()
                        end)
                    end
                end)
            end)
        end
    end

    return cell
end

--播放剧情
function UIMainChapterSideLinePopupDialog:PlayPlot(id, endCb)
    if self.isPlayPlot then
        return
    end
    self.isPlayPlot = true
    local vo = QuestConfMgr:GetInstance():GetQuestSideVo(id)

    local plotIds = CfUtils.Split(vo.plotId)
    if not plotIds then
        GameUtils.Toast(localize("该关卡没有剧情参数"))
        return 
    end

    self.curPlotIndex = 1
    self:PlayPloting(plotIds, endCb)
end

function UIMainChapterSideLinePopupDialog:PlayPloting(plotIds, endCb)
    ChapterUtils.ProcessChapter(checkNumber(plotIds[self.curPlotIndex]), function(go)
        self.controller.gameObject.transform.localPosition = Vector3(9999, 9999, 9999)
        self._lastPageGo.transform.localPosition = Vector3(9999, 9999, 9999)
        self._plotGo = go
    end, function()
        --所有的播完结束
        if self.curPlotIndex >= table.count(plotIds) then
            if endCb then
                endCb()
            end

            self.controller.gameObject.transform.localPosition = Vector3(0, 0, 0)
            self._lastPageGo.transform.localPosition = Vector3(0, 0, 0)
            KTool.SafeDelete(self._plotGo)
            self.isPlayPlot = false

            local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
            CriWareUtils.PlayMusicById("bgm_instance_halloween")
        else
            self.curPlotIndex = self.curPlotIndex + 1
            KTool.SafeDelete(self._plotGo)
            self:PlayPloting(plotIds, endCb)
        end
    end)
end

